from pathlib import Path
from textual.app import App, ComposeResult
from textual.containers import Horizontal
from textual.widgets import Header, Footer, Tree, TextArea
from textual.widgets.tree import TreeNode


class DirectoryBrowserApp(App):
    """A Textual app with a directory tree on the left and text area on the right."""

    CSS = """
    Screen {
        layout: vertical;
    }

    #main_container {
        height: 1fr;
        layout: horizontal;
    }

    #tree_panel {
        width: 1fr;
        border: solid green;
    }

    #text_panel {
        width: 2fr;
        border: solid blue;
    }
    """

    BINDINGS = [("q", "quit", "Quit")]

    def compose(self) -> ComposeResult:
        yield Header()
        with Horizontal(id="main_container"):
            yield Tree(".", id="tree_panel")
            yield TextArea(id="text_panel")
        yield Footer()

    def on_mount(self) -> None:
        tree = self.query_one(Tree)
        self._populate_tree(tree.root, Path("."), max_depth=3)

    def _populate_tree(self, node: TreeNode, path: Path, max_depth: int = 0) -> None:
        """Recursively populate tree with directory contents."""
        if max_depth < 0:
            return

        try:
            items = sorted(path.iterdir())
        except (PermissionError, OSError):
            return

        for item in items:
            if item.name.startswith("."):
                continue

            if item.is_dir():
                child = node.add(f"📁 {item.name}")
                if max_depth > 0:
                    self._populate_tree(child, item, max_depth - 1)
            else:
                node.add(f"📄 {item.name}")


if __name__ == "__main__":
    app = DirectoryBrowserApp()
    app.run()

